import React, { useEffect, useState } from "react";
import axios from "axios";
import "./CreateGroupPage.css";
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import AdminSidebar from "../components/AdminSideBar";

function CreateGroupPage() {
  const [groupNumber, setGroupNumber] = useState("");
  const [projectName, setProjectName] = useState("");
  const [selectedMembers, setSelectedMembers] = useState([]);
  const [supervisor, setSupervisor] = useState("");
  const [evaluator, setEvaluator] = useState("");

  const [students, setStudents] = useState([]);
  const [supervisors, setSupervisors] = useState([]);
  const [evaluators, setEvaluators] = useState([]);
  const [allGroups, setAllGroups] = useState([]);

  // Load data on mount
  useEffect(() => {
    fetchInitialData();
  }, []);

  const fetchInitialData = async () => {
    try {
      const [studentsRes, supervisorsRes, evaluatorsRes, groupsRes] = await Promise.all([
        axios.get("http://localhost:5000/api/student"),
        axios.get("http://localhost:5000/api/facultyAdvisor"),
        axios.get("http://localhost:5000/api/evaluator"),
        axios.get("http://localhost:5000/api/group"),
      ]);
      setStudents(studentsRes.data);
      setSupervisors(supervisorsRes.data);
      setEvaluators(evaluatorsRes.data);
      setAllGroups(groupsRes.data);
    } catch (err) {
      console.error("Error loading data:", err);
    }
  };

  const handleMemberSelection = (student) => {
    if (selectedMembers.some((m) => m._id === student._id)) {
      setSelectedMembers(selectedMembers.filter((m) => m._id !== student._id));
    } else if (selectedMembers.length < 4) {
      setSelectedMembers([...selectedMembers, student]);
    } else {
      alert("You can select up to 4 members only.");
    }
  };

  const handleGroupCreation = async (e) => {
    e.preventDefault();
    if (
      !groupNumber.trim() ||
      !projectName.trim() ||
      selectedMembers.length === 0 ||
      !supervisor ||
      !evaluator
    ) {
      alert("Please fill all fields, select members, supervisor, and evaluator.");
      return;
    }

    try {
      // 1. Create project
      const projectRes = await axios.post("http://localhost:5000/api/project", {
        title: projectName,
        status: "In Progress",
      });

      // 2. Create group
      const groupPayload = {
        groupNo: groupNumber,
        studentsRegno: selectedMembers.map((s) => s.regNo),
        projectID: projectRes.data._id,
        supervisorID: supervisor,
        evaluatorID: evaluator,
      };

      await axios.post("http://localhost:5000/api/group", groupPayload);

      // 3. Update isGrouped for each selected student
      await Promise.all(
        selectedMembers.map((student) =>
          axios.patch(`http://localhost:5000/api/student/regNo/${student.regNo}`, {
            isGrouped: true,
          })
        )
      );

      // 4. Reset form and reload data
      setGroupNumber("");
      setProjectName("");
      setSelectedMembers([]);
      setSupervisor("");
      setEvaluator("");
      fetchInitialData();
      alert("Group created successfully!");
    } catch (err) {
      console.error("Error creating group:", err);
      alert("Failed to create group.");
    }
  };

  const handleDisbandGroup = async (groupId) => {
    const confirmDelete = window.confirm("Are you sure you want to disband this group?");
    if (!confirmDelete) return;

    try {
      const group = allGroups.find((g) => g._id === groupId);
      // 1. Update students' isGrouped to false
      await Promise.all(
        group.studentsRegno.map((regNo) =>
          axios.patch(`http://localhost:5000/api/student/regNo/${regNo}`, {
            isGrouped: false,
          })
        )
      );
      // 2. Delete group
      await axios.delete(`http://localhost:5000/api/group/${groupId}`);
      fetchInitialData();
      alert("Group disbanded successfully.");
    } catch (err) {
      console.error("Failed to disband group:", err);
      alert("Error while disbanding group.");
    }
  };

  return (
    <div className="create-group-container">
      <Navbar />
      <div className="content-wrapper">
        <AdminSidebar />
        <div className="main-content">
          <div className="create-group-section">
            {/* Group Form */}
            <div className="form-container">
              <h2>Create a New Group</h2>
              <form onSubmit={handleGroupCreation}>
                <div className="input-group">
                  <label htmlFor="group-number">Group Number</label>
                  <input
                    type="text"
                    id="group-number"
                    value={groupNumber}
                    onChange={(e) => setGroupNumber(e.target.value)}
                    placeholder="Enter group number"
                    required
                  />
                </div>
                <div className="input-group">
                  <label htmlFor="project-name">Project Name</label>
                  <input
                    type="text"
                    id="project-name"
                    value={projectName}
                    onChange={(e) => setProjectName(e.target.value)}
                    placeholder="Enter project name"
                    required
                  />
                </div>

                {/* Supervisor & Evaluator Dropdowns */}
                <div className="input-group">
                  <label>Supervisor</label>
                  <select
                    value={supervisor}
                    onChange={(e) => setSupervisor(e.target.value)}
                    required
                  >
                    <option value="">-- Select Supervisor --</option>
                    {supervisors.map((sup) => (
                      <option key={sup._id} value={sup._id}>
                        {sup.Name}
                      </option>
                    ))}
                  </select>
                </div>
                <div className="input-group">
                  <label>Evaluator</label>
                  <select
                    value={evaluator}
                    onChange={(e) => setEvaluator(e.target.value)}
                    required
                  >
                    <option value="">-- Select Evaluator --</option>
                    {evaluators.map((evalr) => (
                      <option key={evalr._id} value={evalr._id}>
                        {evalr.name}
                      </option>
                    ))}
                  </select>
                </div>

                <button type="submit" className="submit-button">
                  Create Group
                </button>
              </form>
            </div>

            {/* Student Table */}
            <div className="student-selection">
              <h3>Available Students</h3>
              <table>
                <thead>
                  <tr>
                    <th>Select</th>
                    <th>Name</th>
                    <th>Reg. No</th>
                  </tr>
                </thead>
                <tbody>
                  {students
                    .filter((s) => !s.isGrouped)
                    .map((student) => (
                      <tr key={student._id}>
                        <td>
                          <input
                            type="checkbox"
                            checked={selectedMembers.some((m) => m._id === student._id)}
                            onChange={() => handleMemberSelection(student)}
                          />
                        </td>
                        <td>{student.studentName}</td>
                        <td>{student.regNo}</td>
                      </tr>
                    ))}
                </tbody>
              </table>
            </div>

            {/* Created Groups */}
            <div className="groups-list">
              <h3>Created Groups</h3>
              {allGroups.length > 0 ? (
                <table>
                  <thead>
                    <tr>
                      <th>Group No</th>
                      <th>Project</th>
                      <th>Supervisor</th>
                      <th>Evaluator</th>
                      <th>Members</th>
                      <th>Action</th>
                    </tr>
                  </thead>
                  <tbody>
                    {allGroups.map((group) => (
                      <tr key={group._id}>
                        <td>{group.groupNo}</td>
                        <td>{group.projectID}</td>
                        <td>
                          {supervisors.find((s) => s._id === group.supervisorID)?.Name || "N/A"}
                        </td>
                        <td>
                          {evaluators.find((e) => e._id === group.evaluatorID)?.name || "N/A"}
                        </td>
                        <td>
                          <ul>
                            {group.studentsRegno.map((regNo, idx) => (
                              <li key={idx}>{regNo}</li>
                            ))}
                          </ul>
                        </td>
                        <td>
                          <button onClick={() => handleDisbandGroup(group._id)} className="delete-button">
                            Disband
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              ) : (
                <p>No groups created yet.</p>
              )}
            </div>
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
}

export default CreateGroupPage;
